    "tipo": "juridica",
    "objetivo": "Mapear a un objetivo específico del temario PF92 antes de aprobar",
    "competenciaOriginal": "A",
    "pregunta": "El principio de pasividad procesal significa que:",
    "opciones": [
      {
        "id": "A",
        "text": "Los jueces deben actuar siempre de oficio"
      },
      {
        "id": "B",
        "text": "Los tribunales solo ejercen su ministerio a petición de parte, salvo excepciones legales"
      },
      {
        "id": "C",
        "text": "Las partes no pueden hacer nada sin el juez"
      },
      {
        "id": "D",
        "text": "Los jueces son pasivos frente al Ejecutivo"
      }
    ],
    "respuesta": 1,
