    "tipo": "juridica",
    "objetivo": "Mapear a un objetivo específico del temario PF92 antes de aprobar",
    "competenciaOriginal": "B",
    "pregunta": "Un demandado es notificado en Valdivia de una demanda presentada en Santiago. El plazo base para contestar es de 18 días y la tabla de emplazamiento señala 3 días. ¿Cuál es el plazo total?",
    "opciones": [
      {
        "id": "A",
        "text": "15 días"
      },
      {
        "id": "B",
        "text": "18 días"
      },
      {
        "id": "C",
        "text": "21 días"
      },
      {
        "id": "D",
        "text": "24 días"
      }
    ],
    "respuesta": 2,
    "explicacion": "Art. 259 CPC: 18 días base + 3 días de tabla de emplazamiento = 21 días hábiles. (Fuente: CPC_259)",
