    "pregunta": "Un fiscal formaliza la investigación el 10 de enero de 2024. Sin actividad hasta el 10 de diciembre de 2025. ¿Puede el imputado solicitar el sobreseimiento definitivo?",
    "opciones": [
      {
        "id": "A",
        "text": "No, porque el plazo de 2 años aún no vence"
      },
      {
        "id": "B",
        "text": "Sí, porque han transcurrido más de 2 años sin actividad"
      },
      {
        "id": "C",
        "text": "Sí, pero solo si el fiscal no solicita ampliación"
      },
      {
        "id": "D",
        "text": "No, porque el plazo es de 3 años"
      }
    ],
    "respuesta": 1,
    "explicacion": "Art. 234 y 247 CPP: El plazo máximo de investigación es de 2 años. Vencido sin ampliación, el imputado puede solicitar el sobreseimiento definitivo. (Fuente: CPP_234_247)",
