    "competenciaOriginal": "B",
    "pregunta": "Una parte designa domicilio electrónico para notificaciones. El tribunal envía la sentencia definitiva a ese correo. ¿Es válida la notificación?",
    "opciones": [
      {
        "id": "A",
        "text": "No, porque las sentencias definitivas deben notificarse por cédula"
      },
      {
        "id": "B",
        "text": "Sí, porque la notificación electrónica aceptada por la parte es válida para todas las resoluciones"
      },
      {
        "id": "C",
        "text": "No, porque la notificación electrónica solo aplica a decretos"
      },
      {
        "id": "D",
        "text": "Sí, pero solo si el tribunal lo autoriza expresamente"
      }
    ],
    "respuesta": 1,
    "explicacion": "Art. 8 Ley 20.886: La notificación electrónica aceptada por el tribunal es válida para todo el proceso, incluyendo sentencias definitivas. (Fuente: Ley_20886_8)",
