    "tipo": "juridica",
    "objetivo": "Mapear a un objetivo específico del temario PF92 antes de aprobar",
    "competenciaOriginal": "B",
    "pregunta": "El estado diario electrónico se forma:",
    "opciones": [
      {
        "id": "A",
        "text": "Manualmente en cada tribunal"
      },
      {
        "id": "B",
        "text": "Centralizadamente por la Corporación Administrativa del..."
      },
      {
        "id": "C",
        "text": "Por el secretario del tribunal"
      },
      {
        "id": "D",
        "text": "Solo los días viernes"
      }
    ],
    "respuesta": 1,
    "explicacion": "Art. 50 CPC (modificado por Ley 20.886): La formación del estado diario es centralizada y está a cargo de la CAPJ. (Fuente: CPC_50_Ley20886)",
