    "materia": "Derecho civil y procesal civil",
    "area": "civil",
    "tipo": "juridica",
    "objetivo": "Mapear a un objetivo específico del temario PF92 antes de aprobar",
    "competenciaOriginal": "B",
    "pregunta": "En el juicio ordinario civil de mayor cuantía, ¿cuál es el plazo para contestar la demanda si el demandado es notificado en la misma comuna del tribunal?",
    "opciones": [
      {
        "id": "A",
        "text": "5 días"
      },
      {
        "id": "B",
        "text": "8 días"
      },
      {
        "id": "C",
        "text": "15 días"
      },
      {
        "id": "D",
        "text": "18 días"
      }
    ],
    "respuesta": 2,
    "explicacion": "Art. 258 CPC: Si el demandado es notificado en la comuna donde funciona el tribunal, el plazo es de 15 días. (Fuente: CPC_258)",
