    "tipo": "juridica",
    "objetivo": "Mapear a un objetivo específico del temario PF92 antes de aprobar",
    "competenciaOriginal": "B",
    "pregunta": "Para que proceda la ejecución forzada en el juicio ejecutivo civil, se requiere que la obligación conste en un título al que la ley le atribuya mérito ejecutivo. ¿Cuál de los siguientes NO es un título ejecutivo según el art. 434 del CPC?",
    "opciones": [
      {
        "id": "A",
        "text": "Sentencia firme, definitiva o interlocutoria"
      },
      {
        "id": "B",
        "text": "Copia autorizada de escritura pública"
      },
      {
        "id": "C",
        "text": "Instrumento privado no reconocido judicialmente"
      },
      {
        "id": "D",
        "text": "Confesión judicial"
      }
    ],
    "respuesta": 2,
    "explicacion": "Art. 434 N° 4 CPC: El instrumento privado solo tiene mérito ejecutivo cuando ha sido reconocido judicialmente o mandado tener por reconocido. (Fuente: CPC_434)",
