    "materia": "Derecho civil y procesal civil",
    "area": "civil",
    "tipo": "juridica",
    "objetivo": "Mapear a un objetivo específico del temario PF92 antes de aprobar",
    "competenciaOriginal": "B",
    "pregunta": "La resolución que recibe la causa a prueba en el juicio ordinario debe:",
    "opciones": [
      {
        "id": "A",
        "text": "Señalar los hechos sustanciales, pertinentes y controvertidos"
      },
      {
        "id": "B",
        "text": "Citar a las partes a oír sentencia"
      },
      {
        "id": "C",
        "text": "Fijar el día de la conciliación"
      },
      {
        "id": "D",
        "text": "Ordenar el embargo de bienes"
      }
    ],
    "respuesta": 0,
    "explicacion": "Art. 320 CPC: La resolución que recibe la causa a prueba fija los hechos sustanciales, pertinentes y controvertidos. (Fuente: CPC_320)",
