    "materia": "Derecho penal y procesal penal",
    "area": "penal",
    "tipo": "juridica",
    "objetivo": "Mapear a un objetivo específico del temario PF92 antes de aprobar",
    "competenciaOriginal": "B",
    "pregunta": "El juicio oral en materia penal se desarrolla ante:",
    "opciones": [
      {
        "id": "A",
        "text": "El juez de garantía"
      },
      {
        "id": "B",
        "text": "El Tribunal de Juicio Oral en lo Penal"
      },
      {
        "id": "C",
        "text": "La Corte de Apelaciones"
      },
      {
        "id": "D",
        "text": "El fiscal instructor"
      }
    ],
    "respuesta": 1,
    "explicacion": "Los Tribunales de Juicio Oral en lo Penal conocen y juzgan las causas por crimen o simple delito en un juicio oral y público (art. 17 COT). (Fuente: COT_17)",
