    "materia": "Derecho penal y procesal penal",
    "area": "penal",
    "tipo": "juridica",
    "objetivo": "Mapear a un objetivo específico del temario PF92 antes de aprobar",
    "competenciaOriginal": "B",
    "pregunta": "La audiencia de control de detención debe realizarse dentro de:",
    "opciones": [
      {
        "id": "A",
        "text": "12 horas desde la notificación de detención al detenido"
      },
      {
        "id": "B",
        "text": "24 horas desde que el detenido es puesto a disposición del tribunal"
      },
      {
        "id": "C",
        "text": "48 horas desde la aprehensión del detenido"
      },
      {
        "id": "D",
        "text": "72 horas desde que la autoridad policía notifica la detención"
      }
    ],
    "respuesta": 1,
    "explicacion": "Art. 131 CPP: El detenido debe ser puesto a disposición del juez dentro de 24 horas desde la detención. (Fuente: CPP_131)",
