    "materia": "Derecho penal y procesal penal",
    "area": "penal",
    "tipo": "juridica",
    "objetivo": "Mapear a un objetivo específico del temario PF92 antes de aprobar",
    "competenciaOriginal": "C",
    "pregunta": "Un fiscal ofrece suspensión condicional del procedimiento a un imputado sin condenas previas. ¿Qué ventaja principal tiene esta salida alternativa para el imputado?",
    "opciones": [
      {
        "id": "A",
        "text": "Extingue la responsabilidad penal inmediatamente"
      },
      {
        "id": "B",
        "text": "Suspende el procedimiento y, cumplidas las condiciones,..."
      },
      {
        "id": "C",
        "text": "Reduce la pena en un grado"
      },
      {
        "id": "D",
        "text": "Elimina los antecedentes penales del imputado"
      }
    ],
    "respuesta": 1,
    "explicacion": "Art. 237 y 240 CPP: La suspensión condicional suspende el procedimiento por un período determinado; si se cumplen las condiciones, se decreta sobreseimiento definitivo. (Fuente: CPP_237_240)",
