    "materia": "Derecho penal y procesal penal",
    "area": "penal",
    "tipo": "juridica",
    "objetivo": "Mapear a un objetivo específico del temario PF92 antes de aprobar",
    "competenciaOriginal": "D",
    "pregunta": "Un juez de garantía decreta prisión preventiva sin que existan antecedentes que justifiquen la existencia del delito (solo hay una denuncia sin corroboración). ¿Qué vicio presenta la resolución?",
    "opciones": [
      {
        "id": "A",
        "text": "Infracción al art. 140 CPP por falta de presupuesto material"
      },
      {
        "id": "B",
        "text": "Inconstitucionalidad de la prisión preventiva"
      },
      {
        "id": "C",
        "text": "Nulidad del auto de apertura"
      },
      {
        "id": "D",
        "text": "No hay vicio, porque basta la denuncia para decretar la medida"
      }
    ],
    "respuesta": 0,
    "explicacion": "Art. 140 CPP exige antecedentes que justifiquen la existencia del delito y presunciones fundadas de participación. Es un motivo absoluto de nulidad (art. 374 letra a) CPP). (Fuente: CPP_140_374)",
    "fuente": {
      "id": "CPP_140_374",
      "cita": "CPP_140_374",
      "verificada": false,
      "revisadaEn": null
    },
