    "objetivo": "Mapear a un objetivo específico del temario PF92 antes de aprobar",
    "competenciaOriginal": "C",
    "pregunta": "Un acreedor tiene una sentencia civil firme que condena al deudor a pagar $10.000.000. Han pasado 13 meses desde la ejecutoria. ¿Qué procedimiento debe iniciar?",
    "opciones": [
      {
        "id": "A",
        "text": "Cumplimiento incidental"
      },
      {
        "id": "B",
        "text": "Juicio ejecutivo, presentando la sentencia como título..."
      },
      {
        "id": "C",
        "text": "Juicio ordinario de cobro de pesos"
      },
      {
        "id": "D",
        "text": "No puede cobrar, porque la acción ejecutiva prescribió"
      }
    ],
    "respuesta": 1,
    "explicacion": "Art. 237 CPC: Transcurrido más de un año desde la ejecutoria, la sentencia se cumple conforme a las reglas del juicio ejecutivo. (Fuente: CPC_237)",
    "fuente": {
      "id": "CPC_237",
      "cita": "CPC_237",
      "verificada": false,
      "revisadaEn": null
    },
