    "materia": "Derecho de familia",
    "area": "familia",
    "tipo": "juridica",
    "objetivo": "Mapear a un objetivo específico del temario PF92 antes de aprobar",
    "competenciaOriginal": "B",
    "pregunta": "La sentencia definitiva en el procedimiento de familia se dicta:",
    "opciones": [
      {
        "id": "A",
        "text": "Dentro de 10 días desde la conclusión de la audiencia de juicio"
      },
      {
        "id": "B",
        "text": "Verbalmente al término de la audiencia con copia escrita dentro de 5 días"
      },
      {
        "id": "C",
        "text": "Siempre por escrito dentro de 30 días desde la fecha de la audiencia"
      },
      {
        "id": "D",
        "text": "Dentro de 60 días desde que se dicta sentencia definitiva"
      }
    ],
    "respuesta": 1,
    "explicacion": "Art. 66 Ley 19.968: La sentencia se comunica de inmediato al término de la audiencia, pudiendo diferirse la redacción hasta por 5 días. (Fuente: Ley_19968_66)",
