    "materia": "Derecho laboral",
    "area": "laboral",
    "tipo": "juridica",
    "objetivo": "Mapear a un objetivo específico del temario PF92 antes de aprobar",
    "competenciaOriginal": "B",
    "pregunta": "El recurso de unificación de jurisprudencia laboral procede cuando:",
    "opciones": [
      {
        "id": "A",
        "text": "La sentencia es injusta y causa agravio a una de las partes"
      },
      {
        "id": "B",
        "text": "Respecto de la materia de derecho objeto del juicio existen distintas interpretaciones en fallos firmes de tribunales superiores"
      },
      {
        "id": "C",
        "text": "Cualquier error en la valoración de la prueba por parte del juez"
      },
      {
        "id": "D",
        "text": "Una de las partes lo solicita sin necesidad de fundamento"
      }
    ],
    "respuesta": 1,
    "explicacion": "Art. 483 CT: Procede cuando existen distintas interpretaciones sobre una materia de derecho en fallos firmes de tribunales superiores. (Fuente: CT_483)",
