    "explicacion": "Art. 237 CPC: Fuera del año, la sentencia se cumple por vía ejecutiva. Tratándose del Fisco, se aplica el DFL 1 de Hacienda con intervención del CDE. (Fuente: CPC_237_DFL1)",
