    "tipo": "juridica",
    "objetivo": "Mapear a un objetivo específico del temario PF92 antes de aprobar",
    "competenciaOriginal": "B",
    "pregunta": "El acuerdo reparatorio procede en delitos que:",
    "opciones": [
      {
        "id": "A",
        "text": "Afecten siempre la seguridad nacional"
      },
      {
        "id": "B",
        "text": "Afecten bienes jurídicos disponibles de carácter patrim..."
      },
      {
        "id": "C",
        "text": "Sean sancionados con presidio perpetuo"
      },
      {
        "id": "D",
        "text": "Sean de acción pública exclusivamente"
      }
    ],
    "respuesta": 1,
    "explicacion": "Art. 241 CPP: Procede en delitos que afecten bienes jurídicos disponibles de carácter patrimonial, lesiones menos graves o culposos. (Fuente: CPP_241)",
