    "tipo": "juridica",
    "objetivo": "Mapear a un objetivo específico del temario PF92 antes de aprobar",
    "competenciaOriginal": "B",
    "pregunta": "En el procedimiento de violencia intrafamiliar, las medidas cautelares pueden durar:",
