    "objetivo": "Mapear a un objetivo específico del temario PF92 antes de aprobar",
    "competenciaOriginal": "C",
    "pregunta": "En un juicio de divorcio unilateral, el demandante alega cese de convivencia por más de 3 años. El demandado se opone negando el cese. ¿Qué estrategia probatoria es más eficaz para el demandante?",
    "opciones": [
      {
        "id": "A",
        "text": "Solicitar la confesión judicial del demandado"
      },
      {
        "id": "B",
        "text": "Presentar testigos que acrediten la separación de hecho y documentos que demuestren domicilios distintos"
      },
      {
        "id": "C",
        "text": "Solicitar un informe psicosocial del tribunal"
      },
      {
        "id": "D",
        "text": "Pedir que el tribunal presuma el cese por el solo transcurso del tiempo"
      }
    ],
    "respuesta": 1,
    "explicacion": "El cese de convivencia se prueba con testigos y documentos que acrediten la separación material de los cónyuges (art. 55 Ley de Matrimonio Civil). (Fuente: LMC_55)",
