    "objetivo": "Mapear a un objetivo específico del temario PF92 antes de aprobar",
    "competenciaOriginal": "D",
    "pregunta": "Un tribunal de familia decreta una medida de protección. La resolución no es notificada a los padres del niño. ¿Qué vicio se configura?",
    "opciones": [
      {
        "id": "A",
        "text": "Omisión de trámite esencial que causa indefensión"
      },
      {
        "id": "B",
        "text": "Incompetencia del tribunal"
      },
      {
        "id": "C",
        "text": "No hay vicio, porque las medidas de protección son reservadas"
      },
      {
        "id": "D",
        "text": "La medida es nula solo si los padres la impugnan"
      }
    ],
    "respuesta": 0,
    "explicacion": "Los padres tienen derecho a ser oídos y notificados de las medidas que afectan a sus hijos. La falta de notificación causa indefensión. (Fuente: Ley_19968_71)",
