    "competenciaOriginal": "E",
    "pregunta": "Una sala de Corte de Apelaciones queda sin el número de jueces necesarios para resolver. ¿Cómo se integra?",
    "opciones": [
      {
        "id": "A",
        "text": "Con abogados integrantes primero, luego fiscales judiciales"
      },
      {
        "id": "B",
        "text": "Con miembros no inhabilitados, luego fiscales judiciales y finalmente abogados integrantes"
      },
      {
        "id": "C",
        "text": "Con jueces de letras de la jurisdicción"
      },
      {
        "id": "D",
        "text": "Se suspende la causa hasta que se reintegre la sala"
      }
    ],
    "respuesta": 1,
    "explicacion": "Art. 215 COT: Las Cortes se integran con miembros no inhabilitados, fiscales judiciales y abogados integrantes, en ese orden. (Fuente: COT_215)",
