    "competenciaOriginal": "C",
    "pregunta": "Un litigante fue notificado de una sentencia civil adversa el viernes 6 de octubre. El lunes 9 es feriado. ¿Cuándo vence el plazo para apelar?",
    "opciones": [
      {
        "id": "A",
        "text": "El viernes 13 de octubre"
      },
      {
        "id": "B",
        "text": "El viernes 20 de octubre"
      },
      {
        "id": "C",
        "text": "El lunes 16 de octubre"
      },
      {
        "id": "D",
        "text": "El miércoles 18 de octubre"
      }
    ],
    "respuesta": 1,
    "explicacion": "El plazo de 10 días hábiles se cuenta desde el día siguiente a la notificación. Con el feriado del lunes 9, el plazo comienza el martes 10 y vence el viernes 20 de octubre. (Fuente: CPC_189)",
