    "competenciaOriginal": "E",
    "pregunta": "Un litigante interpone recurso de casación en la forma sin haber preparado el recurso (no reclamó el vicio en la instancia). ¿Qué consecuencia se produce?",
    "opciones": [
      {
        "id": "A",
        "text": "El recurso debe declararse inadmisible por falta de preparación"
      },
      {
        "id": "B",
        "text": "El recurso es admisible, pero se rechazará en el fondo"
      },
      {
        "id": "C",
        "text": "La Corte debe dar plazo para preparar el recurso"
      },
      {
        "id": "D",
        "text": "El recurso se convierte en apelación"
      }
    ],
    "respuesta": 0,
    "explicacion": "Art. 769 CPC: El recurso de casación en la forma requiere preparación; la falta de reclamación oportuna acarrea la inadmisibilidad. (Fuente: CPC_769_781)",
