    "opciones": [
      {
        "id": "A",
        "text": "El Ministerio Público directamente"
      },
      {
        "id": "B",
        "text": "El juez de garantía competente"
      },
      {
        "id": "C",
        "text": "Gendarmería de Chile, con exclusividad"
      },
      {
        "id": "D",
        "text": "La Corte de Apelaciones"
      }
    ],
    "respuesta": 1,
    "explicacion": "Art. 466 y ss. CPP: El juez de garantía supervisa la ejecución de la pena. (Fuente: CPP_466)",
