    "objetivo": "Mapear a un objetivo específico del temario PF92 antes de aprobar",
    "competenciaOriginal": "D",
    "pregunta": "En un juicio ejecutivo, se embarga un bien que es de propiedad de un tercero. ¿Qué puede hacer el tercero?",
    "opciones": [
      {
        "id": "A",
        "text": "Nada, porque el embargo es definitivo"
      },
      {
        "id": "B",
        "text": "Interponer una tercería de dominio"
      },
      {
        "id": "C",
        "text": "Solicitar la nulidad del juicio ejecutivo"
      },
      {
        "id": "D",
        "text": "Demandar al acreedor por daños"
      }
    ],
    "respuesta": 1,
