    "objetivo": "Mapear a un objetivo específico del temario PF92 antes de aprobar",
    "competenciaOriginal": "E",
    "pregunta": "Un alimentante adeuda 6 meses de pensión alimenticia. El tribunal decreta arresto nocturno por 15 días. ¿Puede repetirse la medida?",
    "opciones": [
      {
        "id": "A",
        "text": "No, porque el arresto solo puede decretarse una vez"
      },
      {
        "id": "B",
        "text": "Sí, hasta obtener el íntegro pago"
      },
      {
        "id": "C",
        "text": "Sí, pero solo después de 3 meses"
      },
      {
        "id": "D",
        "text": "No, porque debe intentarse otra medida"
      }
    ],
    "respuesta": 1,
    "explicacion": "Art. 14 Ley 14.908: El arresto nocturno puede repetirse cuantas veces sea necesario hasta obtener el pago íntegro. (Fuente: Ley_14908_14)",
