    "tipo": "juridica",
    "objetivo": "Mapear a un objetivo específico del temario PF92 antes de aprobar",
    "competenciaOriginal": "C",
    "pregunta": "Un abogado necesita presentar un escrito de apelación de plazo. La OJV presenta una caída del sistema. ¿Qué debe hacer?",
