    "pregunta": "La duración de los alegatos ante las Cortes de Apelaciones es, por regla general, de:",
    "opciones": [
      {
        "id": "A",
        "text": "15 minutos"
      },
      {
        "id": "B",
        "text": "30 minutos, prorrogables"
      },
      {
        "id": "C",
        "text": "1 hora"
      },
      {
        "id": "D",
        "text": "Sin límite de tiempo"
      }
    ],
    "respuesta": 1,
    "explicacion": "Art. 223 inc. 4° CPC: Los alegatos pueden durar hasta media hora, pero el tribunal puede prorrogar el plazo. (Fuente: CPC_223)",
