    "tipo": "juridica",
    "objetivo": "Mapear a un objetivo específico del temario PF92 antes de aprobar",
    "competenciaOriginal": "C",
    "pregunta": "Un litigante desea que la Corte de Apelaciones suspenda los efectos de una sentencia mientras se tramita la apelación. ¿Qué debe solicitar?",
    "opciones": [
      {
        "id": "A",
        "text": "Orden de no innovar"
      },
      {
        "id": "B",
        "text": "Medida cautelar innominada"
      },
      {
        "id": "C",
        "text": "Suspensión del procedimiento"
      },
      {
        "id": "D",
        "text": "No puede solicitarse en segunda instancia"
      }
    ],
    "respuesta": 0,
    "explicacion": "Art. 192 CPC: La ONI procede a petición del apelante cuando la apelación se concede en el solo efecto devolutivo. (Fuente: CPC_192)",
