    "competenciaOriginal": "B",
    "pregunta": "En materia de familia, el recurso de apelación se concede:",
    "opciones": [
      {
        "id": "A",
        "text": "Siempre en ambos efectos"
      },
      {
        "id": "B",
        "text": "Solo en el efecto devolutivo, salvo excepciones"
      },
      {
        "id": "C",
        "text": "En el efecto suspensivo"
      },
      {
        "id": "D",
        "text": "A elección del tribunal"
      }
    ],
    "respuesta": 1,
    "explicacion": "Art. 67 N° 3 Ley 19.968: La apelación en familia se concede solo en el efecto devolutivo, salvo acciones de estado civil. (Fuente: Ley_19968_67)",
