    "tipo": "juridica",
    "objetivo": "Mapear a un objetivo específico del temario PF92 antes de aprobar",
    "competenciaOriginal": "B",
    "pregunta": "En el juicio ejecutivo civil, si el deudor no opone excepciones:",
    "opciones": [
      {
        "id": "A",
        "text": "Se dicta sentencia absolutoria"
      },
      {
        "id": "B",
        "text": "Se omite la sentencia y basta el mandamiento de ejecución"
      },
      {
        "id": "C",
        "text": "Se archiva la causa"
      },
      {
        "id": "D",
        "text": "Se cita a conciliación"
      }
    ],
    "respuesta": 1,
