    "materia": "Derecho público · constitucional",
    "area": "principios",
    "tipo": "juridica",
    "objetivo": "Mapear a un objetivo específico del temario PF92 antes de aprobar",
    "competenciaOriginal": "A",
    "pregunta": "¿Cuál de las siguientes es una característica de los tribunales colegiados?",
    "opciones": [
      {
        "id": "A",
        "text": "Resuelven siempre con un solo juez"
      },
      {
        "id": "B",
        "text": "La decisión se forma por mayoría de votos de sus miembros"
      },
      {
        "id": "C",
        "text": "No existen en Chile"
      },
      {
        "id": "D",
        "text": "Solo conocen causas de mínima cuantía"
      }
    ],
    "respuesta": 1,
    "explicacion": "Las Cortes de Apelaciones y el Tribunal de Juicio Oral son ejemplos de tribunales colegiados (art. 72 COT). (Fuente: COT_72)",
