    "materia": "Derecho civil y procesal civil",
    "area": "civil",
    "tipo": "juridica",
    "objetivo": "Mapear a un objetivo específico del temario PF92 antes de aprobar",
    "competenciaOriginal": "B",
    "pregunta": "Las medidas para mejor resolver pueden decretarse:",
    "opciones": [
      {
        "id": "A",
        "text": "En cualquier momento del juicio"
      },
      {
        "id": "B",
        "text": "Solo dentro del plazo para dictar sentencia"
      },
      {
        "id": "C",
        "text": "Antes de la contestación de la demanda"
      },
      {
        "id": "D",
        "text": "Únicamente en segunda instancia"
      }
    ],
    "respuesta": 1,
    "explicacion": "Art. 159 CPC: Las medidas para mejor resolver se decretan una vez vencido el término probatorio y dentro del plazo para fallar. (Fuente: CPC_159)",
