    "tipo": "juridica",
    "objetivo": "Mapear a un objetivo específico del temario PF92 antes de aprobar",
    "competenciaOriginal": "C",
    "pregunta": "Un demandante obtiene sentencia favorable en un juicio ordinario. La sentencia es apelada en ambos efectos. ¿Puede solicitar su ejecución provisional?",
    "opciones": [
      {
        "id": "A",
        "text": "Sí, porque toda sentencia favorable es ejecutable"
      },
      {
        "id": "B",
        "text": "No, porque la concesión en ambos efectos suspende la ejecución"
      },
      {
        "id": "C",
        "text": "Sí, pero solo si presta caución"
      },
      {
        "id": "D",
        "text": "Sí, solicitando orden de no innovar"
      }
    ],
    "respuesta": 1,
    "explicacion": "Art. 231 CPC: Si la apelación se concede en ambos efectos, la sentencia no puede ejecutarse mientras esté pendiente el recurso. (Fuente: CPC_231)",
