    "objetivo": "Mapear a un objetivo específico del temario PF92 antes de aprobar",
    "competenciaOriginal": "B",
    "pregunta": "Cuando una sala de Corte de Apelaciones queda sin el número de jueces necesarios:",
    "opciones": [
      {
        "id": "A",
        "text": "Se archiva la causa"
      },
      {
        "id": "B",
        "text": "Se integra con fiscales judiciales o abogados integrantes"
      },
      {
        "id": "C",
        "text": "Se espera hasta que regresen los ministros"
      },
      {
        "id": "D",
        "text": "Se envía a la Corte Suprema"
      }
    ],
    "respuesta": 1,
    "explicacion": "Art. 215 COT: Las Cortes se integran con miembros no inhabilitados, fiscales judiciales y abogados integrantes. (Fuente: COT_215)",
