    "competenciaOriginal": null,
    "pregunta": "Una sentencia ejecutoriada condena al Fisco a pagar. El ministerio respectivo recibió el oficio del tribunal con los antecedentes exigidos. ¿Qué regla rige el cumplimiento?",
    "opciones": [
      {
        "id": "A",
        "text": "Embargo inmediato una vez transcurridos cinco días desde la ejecutoria."
      },
      {
        "id": "B",
        "text": "Pago por decreto dentro de sesenta días desde la recepción del oficio."
      },
      {
        "id": "C",
        "text": "Cumplimiento incidental dentro de noventa días desde la ejecutoria."
      },
      {
        "id": "D",
        "text": "Nuevo juicio ejecutivo al cumplirse un año desde el oficio."
      }
    ],
    "respuesta": 1,
    "explicacion": "El artículo 752 establece una vía especial y un hito de cómputo propio. No trasladar mecánicamente el año del artículo 233.",
