    "materia": "Reformulación · Inembargabilidad de sueldo público",
    "area": "reformulada",
    "tipo": "diagnostica",
    "objetivo": "Repaso aplicado; confirmar objetivo PF92 antes de simulación formal",
    "competenciaOriginal": null,
    "pregunta": "En la ejecución de un crédito bancario común se pretende embargar la parte del sueldo de un funcionario estatutario pagado por el Estado que excede de 56 UF. No se invoca una excepción especial. ¿Qué debe resolverse?",
    "opciones": [
      {
        "id": "A",
        "text": "Rechazarlo por la protección especial de ese sueldo."
      },
      {
        "id": "B",
        "text": "Autorizarlo porque todo sueldo tiene el mismo umbral."
      },
      {
        "id": "C",
        "text": "Autorizar hasta la mitad, aunque no se cobren alimentos."
      },
      {
        "id": "D",
        "text": "Diferirlo hasta conocer la antigüedad del funcionario."
      }
    ],
    "respuesta": 0,
    "explicacion": "La regla del CPC 445 N°1 es distinta del régimen general de remuneraciones laborales. El caso excluye deudas alimenticias y otras excepciones.",
