    "materia": "Reformulación · Mérito ejecutivo de pagaré",
    "area": "reformulada",
    "tipo": "diagnostica",
    "objetivo": "Repaso aplicado; confirmar objetivo PF92 antes de simulación formal",
    "competenciaOriginal": null,
    "pregunta": "Un pagaré vencido contiene una obligación líquida, actualmente exigible y no prescrita. La firma del suscriptor fue autorizada por notario. ¿Es necesario preparar la ejecución por reconocimiento judicial de firma?",
    "opciones": [
      {
        "id": "A",
        "text": "Sí, porque todo pagaré exige esa diligencia antes de ejecutarse."
      },
      {
        "id": "B",
        "text": "Sí, salvo que el deudor comparezca voluntariamente a pagar."
      },
      {
        "id": "C",
        "text": "No, porque concurre una hipótesis legal que la hace innecesaria."
      },
      {
        "id": "D",
        "text": "No, porque basta la liquidez aun cuando falte todo título."
      }
    ],
    "respuesta": 2,
    "explicacion": "La firma autorizada activa una hipótesis del CPC 434 N°4. No suprimir el análisis de los restantes requisitos ejecutivos.",
