    "competenciaOriginal": null,
    "pregunta": "Una sentencia ordena pagar al cumplirse un plazo posterior a su ejecutoria. Al pedir cumplimiento han pasado trece meses desde la ejecutoria, pero ocho desde la exigibilidad. Se pide ante el tribunal que la dictó y no existe régimen especial. ¿Qué hito determina el año del cumplimiento incidental?",
    "opciones": [
      {
        "id": "A",
        "text": "La fecha en que la demanda original fue notificada."
      },
      {
        "id": "B",
        "text": "La fecha en que la ejecución se hizo exigible."
      },
      {
        "id": "C",
        "text": "La fecha en que la sentencia se pronunció oralmente."
      },
      {
        "id": "D",
        "text": "La fecha en que el acreedor conoció bienes embargables."
      }
    ],
    "respuesta": 1,
    "explicacion": "El artículo 233 emplea exigibilidad. La firmeza no siempre coincide con el inicio de la obligación de cumplir.",
