    "competenciaOriginal": null,
    "pregunta": "Una sentencia definitiva civil se notifica válidamente el viernes 6 de octubre de 2023. El lunes 9 es feriado; no hay otros festivos en el intervalo. Conforme al cómputo del CPC, ¿cuándo vence el término de diez días para apelar?",
    "opciones": [
      {
        "id": "A",
        "text": "El miércoles 18 de octubre de 2023."
      },
      {
        "id": "B",
        "text": "El jueves 19 de octubre de 2023."
      },
      {
        "id": "C",
        "text": "El viernes 20 de octubre de 2023."
      },
      {
        "id": "D",
        "text": "El lunes 23 de octubre de 2023."
      }
    ],
    "respuesta": 1,
    "explicacion": "Días computados: 7, 10, 11, 12, 13, 14, 16, 17, 18 y 19. Se excluyen domingos y el festivo del día 9; el sábado no se excluye por ser sábado.",
