    "objetivo": "Repaso aplicado; confirmar objetivo PF92 antes de simulación formal",
    "competenciaOriginal": null,
    "pregunta": "El imputado reúne los requisitos personales para una suspensión condicional, pero el fiscal no solicita ni acuerda esa salida. ¿Puede el juez imponerla sólo porque la defensa la pide?",
    "opciones": [
      {
        "id": "A",
        "text": "Sí, si el imputado no registra condenas anteriores."
      },
      {
        "id": "B",
        "text": "No, porque la salida exige la intervención y acuerdo legalmente previstos."
      },
      {
        "id": "C",
        "text": "Sí, si la víctima declara que prefiere evitar el juicio."
      },
      {
        "id": "D",
        "text": "No, porque la suspensión exige una condena ejecutoriada."
      }
    ],
    "respuesta": 1,
    "explicacion": "Reunir requisitos personales no sustituye la solicitud fiscal con acuerdo del imputado. Separar requisitos, duración, efectos y revocación en variantes diferentes.",
