    "originalIds": [
      306,
      115,
      442
    ],
    "materia": "Reformulación · Abreviado no equivale a condena asegurada",
    "area": "reformulada",
    "tipo": "diagnostica",
    "objetivo": "Repaso aplicado; confirmar objetivo PF92 antes de simulación formal",
    "competenciaOriginal": null,
    "pregunta": "La defensa explica al imputado un eventual abreviado. ¿Cuál afirmación evita confundir aceptación del procedimiento con un resultado obligatorio?",
    "opciones": [
      {
        "id": "A",
        "text": "La aceptación obliga al juez a condenar en los términos pedidos."
      },
      {
        "id": "B",
        "text": "La aceptación impide al juez revisar los antecedentes de investigación."
      },
      {
        "id": "C",
        "text": "La aceptación no releva al juez de fundar su decisión ni excluye una absolución."
      },
      {
        "id": "D",
        "text": "La aceptación equivale a renunciar a toda impugnación de la sentencia."
      }
    ],
    "respuesta": 2,
    "explicacion": "El artículo 412 exige fundamento y prohíbe condenar sólo por aceptación. El consentimiento debe ser informado; no prometer condena ni absolución.",
