    "tipo": "diagnostica",
    "objetivo": "Repaso aplicado; confirmar objetivo PF92 antes de simulación formal",
    "competenciaOriginal": null,
    "pregunta": "Una demanda civil omite la individualización indispensable del demandado. El juez advierte el defecto al examinarla. ¿Qué actuación es compatible con su función?",
    "opciones": [
      {
        "id": "A",
        "text": "No darle curso, expresando el defecto legal advertido."
      },
      {
        "id": "B",
        "text": "Construir de oficio la identidad de la persona que conviene demandar."
      },
      {
        "id": "C",
        "text": "Admitirla, pues cualquier control formal vulneraría imparcialidad."
      },
      {
        "id": "D",
        "text": "Rechazar definitivamente el derecho sustantivo del actor."
      }
    ],
