    "materia": "Reformulación · Amistad y causal legal",
    "area": "reformulada",
    "tipo": "diagnostica",
    "objetivo": "Repaso aplicado; confirmar objetivo PF92 antes de simulación formal",
    "competenciaOriginal": null,
    "pregunta": "Un juez y una de las partes mantienen un vínculo documentado de amistad que se manifiesta por actos de estrecha familiaridad. ¿Qué institución debe examinarse?",
    "opciones": [
      {
        "id": "A",
        "text": "Implicancia por la sola coincidencia de domicilio comunal."
      },
      {
        "id": "B",
        "text": "Recusación por el vínculo de amistad legalmente descrito."
      },
      {
        "id": "C",
        "text": "Incompetencia absoluta por razón de la materia debatida."
      },
      {
        "id": "D",
        "text": "Inhabilidad automática de todos los jueces del tribunal."
      }
    ],
    "respuesta": 1,
    "explicacion": "El hecho decisivo es la intensidad acreditada del vínculo, no ser excompañeros. Se usa una parte para no trasladar sin análisis la causal al fiscal.",
