function validarBanco(preguntas) {
  if (!Array.isArray(preguntas) || !preguntas.length) throw new Error('Banco vacío');
  const ids = new Set();
  preguntas.forEach((p, i) => {
    if (!p.id || ids.has(p.id)) throw new Error('ID inválido o duplicado en posición ' + i);
    if (!p.pregunta || !Array.isArray(p.opciones) || p.opciones.length !== 4) throw new Error('Pregunta incompleta: ' + p.id);
    if (!Number.isInteger(p.respuesta) || p.respuesta < 0 || p.respuesta > 3) throw new Error('Clave inválida: ' + p.id);
    if (p.opciones.some(o => !o || !o.id || typeof o.text !== 'string' || !o.text.trim())) throw new Error('Alternativa inválida: ' + p.id);
    if (!['provisional', 'revisar', 'bloqueada', 'retirada'].includes(p.estado)) throw new Error('Estado inválido: ' + p.id);
    ids.add(p.id);
  });
  return true;
}
validarBanco(preguntas_banco);
